#!/usr/bin/env python3
import hashlib,json,re,subprocess,sys
from pathlib import Path
assert sys.flags.isolated and sys.flags.no_site
root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign14-tau-lift-check';draft=root/'research/nine-sharing-sign14-tau-lift-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();r=p/'run.py';m=p/'source-manifest.json';assert sha(r)=='beb266f2f240c5c05145d6c87c0a154378f85880a4fe6bad35b529885b2a9291' and sha(m)=='dd7d1c0cddf29c677b1b97a598ff6536b801cadce545716c12dcf7b36a2c25df';row,=json.loads(m.read_text())['rows'];name='Sign14TauLift';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256'] and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.Sign14TauBound','DiophantineConsistency.Sign14ScalarWindow','DiophantineConsistency.Sign14TauValue'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
for t in ('theorem exists_tau_of_seed','(hb : 0 < beta) (hMC : MC < beta) (hMF : MF < 2 * beta)','(hz : InternalZero (SharingSeed14Degree124.seed p) v)','∃ tau : V, ι tau = (SharingSeed14Degree124.shared36 p).evalRing','Sign14ScalarWindow.q_bound_of_seed','Sign14TauValue.tau_eval','Sign14TauBound.tau_embedding','ht.trans he.symm'):assert t in s
assert all('(hp'+i+' : ((p '+i+' : ℤ) : DiffRing V) = ι ' in s for i in ('0','1','2','3'))
survey=p/'provider-survey.py';assert sha(survey)=='39c2136db4ae4853d2a0a1f8c83e1191acc2efbf139e1cfcec4be5a7cbff9044';runner=r.read_text();assert "'-M2800'" in runner and 'rss_limit=4*1024**3,mem_floor=10*1024**3,seconds=120,interval=.1' in runner and "if local in survey['producers']:" in runner
for label,pin in [('tau-bound','afda88705a1c0ec53b728d2a5ad9b32e1dcf47d20886345f0f9d573b699f7285'),('tau-value','17ebd3b63ccb9f8c3336a58aa7cf1edbfb31a5b5933197c706a430c63d984116'),('scalar-window','5b496aff998c350540bccb4567124aa3534f7b1872e59475550d011fdb1782e5')]:
 c=root/('reviews/nine-sharing-sign14-'+label+'-terminal-independent/check.py');assert sha(c)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(c)],capture_output=True,check=True,timeout=120)
z=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,check=True,timeout=180);data=json.loads(z.stdout);assert data['status']=='PASS' and len(data['extra'])==0 and len(data['producers'])==2
x=subprocess.run([sys.executable,'-I','-S','-B',str(r),'--preflight'],capture_output=True,text=True,timeout=180);assert x.returncode==0 and not x.stderr and json.loads(x.stdout)['status']=='PASS_NO_LEAN_PREFLIGHT'
print(json.dumps({'status':'PASS_PRELAUNCH','extra_overlays':0,'scope':'natural tau representation proposal under seed/port/bounds; no equivalence'},indent=2))
